questionvariables.text:
/*--------------------------------------------------------------------------------------------*/
/*Define function S(n) that given a number n, returns the string "+n" if positive (or zero) and "-n" if negative, if n=+1 or -1 it returns + or - respectively*/

S(n):= block([], if (n=1) then return("+") elseif (n=-1) then return("-") elseif (n>=0) then return(vconcat("+", abs(n)))  else  return(vconcat("-", abs(n))));

/*Define function S1(n) that given a number n, returns the string "+n" if positive (or zero) and "-n" if negative (1 and -1 are treated as the other numbers)*/

S1(n):= block([], if (n>=0) then return(vconcat("+", abs(n)))  else  return(vconcat("-", abs(n))));

/*Define function SP(n) that given a number n, returns the string "n" if positive (or zero) and "(-n)" if negative*/

SP(n):= block([], if (n>=0) then return(n)  else  return(vconcat("(-", abs(n), ")")));

/*----------------------------------------------------------------------------------------------------*/


/*generate coefficients for terms in sequence in order to have nice values for x=ta1:
The sequence is a=AAx+BB, a2= CCx+DD, a3= EEx (with AA<0, CC>0, EE>0). In order for it to be arithmetic, it should hold
 (CCx+DD)-(AAx+BB) = EEx-(CCx+DD)
From this we obtain
 x= \frac{-2DD+BB}{2CC-AA-EE}
So we randomly generate AA, CC, EE and x and set SS=x(2CC-AA-EE), so that -2DD+BB=SS. */

AA: -rand(5)-1;
CC:rand(5)+1;
EE:rand(6)+2;

ta1:rand(5)+1;
SS:ta1*(2*CC-AA-EE);

/*Next, we randomly generate DD and then set BB = SS+2DD*/

DD: rand_with_prohib(-10,10,[]);
BB:SS+2*DD;

/*Degenerate cases:
- when x is such that all the terms are the same--> common difference d=0
- when the equation to solve is 0=0 due to the fact that 2C-A-E=0
-->while loop to avoid these 2 cases*/

intersection:(DD-BB)/(AA-CC);  /*the denominator is always nonzero!*/
x_coeff:2*CC-AA-EE;

while (ta1=intersection or x_coeff=0) do (AA: -rand(5)-1,CC:rand(5)+1,EE:rand(6)+2,ta1:rand(5)+1,SS:ta1*(2*CC-AA-EE),DD: rand_with_prohib(-10,10,[]),BB:SS+2*DD,intersection:(DD-BB)/(AA-CC), x_coeff:2*CC-AA-EE)


/*Terms of the puzzle sequence*/
a_1:AA*x+BB;
a_2:CC*x+DD;
a_3:EE*x;

/*common difference*/
ta2:(EE-CC)*ta1-DD;

feedbackvariables.text:
/*dividing instead of subtracting*/
x_from_dividing:allroots((CC*x+DD)^2=EE*x*(AA*x+BB))
zero_denom1:-BB/AA;
zero_denom2:-DD/CC;


/*Thinking each term has to be the same*/
x_12:(DD-BB)/(AA-CC); 
x_23:-DD/(CC-EE);

/*Calculation errors*/
/*wrong brackets*/
x_wr_brackects_left:rhs(solve(CC*x+DD-AA*x+BB=EE*x-CC*x-DD)[1]);
x_wr_brackects_right:rhs(solve(CC*x+DD-AA*x-BB=EE*x-CC*x+DD)[1]);
x_wr_brackects_leftright:rhs(solve(CC*x+DD-AA*x+BB=EE*x-CC*x+DD)[1]);

/*not changing sign to AA (since AA<0)*/
x_AA_no_plus:rhs(solve(CC*x+DD+AA*x-BB=EE*x-CC*x-DD)[1]);

/*combination of wrong brackets and not changing sign to AA*/
x_AA_wr_brackects_left:rhs(solve(CC*x+DD+AA*x+BB=EE*x-CC*x-DD)[1]);
x_AA_wr_brackects_right:rhs(solve(CC*x+DD+AA*x-BB=EE*x-CC*x+DD)[1]);
x_AA_wr_brackects_leftright:rhs(solve(CC*x+DD+AA*x+BB=EE*x-CC*x+DD)[1]);

a_1_x:ev(a_1,x=ta1);
a_2_x:ev(a_2,x=ta1);
a_3_x:ev(a_3,x=ta1);

/*consistent answers from ans1*/
a_1_ans:ev(a_1,x=ans1);
a_2_ans:ev(a_2,x=ans1);
a_3_ans:ev(a_3,x=ans1);
d1_cons:a_2_ans-a_1_ans;
d2_cons:a_3_ans-a_2_ans;
